#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double a, b, U;
    cin >> a >> b >> U;
    int ans = 1;
    if (a <= U) ans++;
    while (b <= U) {
        ans++;
        double t = sqrt(a * a + b * b);
        a = b, b = t;
    }
    cout << ans << endl;
    return 0;
}

